@import url('https://fonts.googleapis.com/css2?family=Ruda:wght@400;500;600;700&family=Inter:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500;600;700&display=swap');

/* FC Porto DNA — dragões blue and white stripes, dragon gold */
.theme-porto {
  --bg: oklch(0.974 0.009 247.9);
  --surface: oklch(1.000 0 0);
  --surface-2: oklch(0.942 0.017 248.0);
  --fg: oklch(0.302 0.074 252.7);
  --fg-muted: oklch(0.593 0.044 253.2);
  --accent: oklch(0.370 0.122 255.1);
  --accent-fg: oklch(1.000 0 0);
  --accent-2: oklch(0.746 0.143 87.5);
  --line: oklch(0.906 0.025 246.2);
  --success: oklch(0.523 0.135 144.2);
  --warning: oklch(0.768 0.158 81.3);
  --danger: oklch(0.55 0.2 27);
  --radius: 0.375rem;
  --radius-sm: 0.25rem;
  --radius-lg: 0.5rem;
  --radius-pill: 9999px;
  --shadow-1: 0 1px 2px oklch(0 0 0 / 8%);
  --shadow-2: 0 6px 20px -8px oklch(0 0 0 / 15%);
  --shadow-3: 0 20px 50px -16px oklch(0 0 0 / 20%);
  --glow: 0 0 0 1px color-mix(in oklab, var(--accent) 45%, transparent);
  --border-width: 1px;
  --blur-amount: 0px;
  --font-display: "Ruda", sans-serif;
  --font-body: "Inter", sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;
  --tracking-display: 0em;
  --label-transform: uppercase;
  --label-tracking: 0.1em;

  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}

.theme-porto h1,
.theme-porto h2,
.theme-porto h3 {
  font-family: var(--font-display);
  letter-spacing: var(--tracking-display);
}

/* signature */
.theme-porto { --font-ui: var(--font-display); }
.theme-porto h1, .theme-porto h2 { text-transform: uppercase; }
.theme-porto button { text-transform: uppercase; letter-spacing: 0.06em; }

.theme-porto { background-image: repeating-linear-gradient(90deg, oklch(0.4 0.09 255 / 7%) 0 40px, transparent 40px 80px); background-size: 100% 260px; background-repeat: no-repeat; }
.theme-porto h1 { font-weight: 700; }
.theme-porto h1::after { content: ""; display: block; height: 3px; width: 5rem; margin-top: 0.6rem; background: var(--accent-2); }

/* depth */
.theme-porto thead th { background: var(--accent); color: oklch(1 0 0); text-transform: uppercase; letter-spacing: 0.1em; font-size: 0.78em; }
.theme-porto td { border-bottom: 1px solid var(--line); }
/* portista stripes: every other row carries the shirt */
.theme-porto tbody tr:nth-child(even) { background: oklch(0.370 0.122 255.1 / 5%); }
.theme-porto tbody tr:hover { background: oklch(0.370 0.122 255.1 / 10%); }
.theme-porto a { color: var(--accent); text-underline-offset: 3px; text-decoration-color: oklch(0.746 0.143 87.5 / 60%); }
.theme-porto a:hover { text-decoration-color: var(--accent-2); text-decoration-thickness: 2px; }
.theme-porto ::selection { background: var(--accent); color: oklch(1 0 0); }
.theme-porto input:focus-visible, .theme-porto select:focus-visible, .theme-porto textarea:focus-visible { outline: 2px solid var(--accent); outline-offset: 1px; }
/* dragon-gold keycap */
.theme-porto kbd { background: oklch(1 0 0); border: 1px solid var(--line); border-bottom: 3px solid var(--accent-2); border-radius: var(--radius-sm); padding: 0.1em 0.45em; font-family: var(--font-mono); color: var(--accent); }
.theme-porto ::-webkit-scrollbar { width: 10px; height: 10px; }
.theme-porto ::-webkit-scrollbar-track { background: var(--surface-2); }
.theme-porto ::-webkit-scrollbar-thumb { background: var(--accent); border-radius: 5px; border: 2px solid var(--surface-2); }
.theme-porto ::-webkit-scrollbar-thumb:hover { background: oklch(0.60 0.12 87); }
.theme-porto .label-caps { color: var(--accent); }
/* azulejo tilework on framed panels */
.theme-porto .themed-border { border-image: repeating-linear-gradient(90deg, oklch(0.370 0.122 255.1) 0 10px, oklch(1 0 0) 10px 20px) 1; }
.theme-porto button:active { transform: translateY(1px); }

/* alt mode: away kit (2026-27 real kit / NBA Association Edition) */
.theme-porto.alt-mode {
  --bg: oklch(0.307 0.100 13.9);
  --surface: oklch(0.346 0.107 13.2);
  --surface-2: oklch(0.385 0.115 12.1);
  --fg: oklch(0.927 0.031 79.9);
  --fg-muted: oklch(0.739 0.046 52.4);
  --accent: oklch(0.880 0.047 80.8);
  --accent-fg: oklch(0.307 0.100 13.9);
  --accent-2: oklch(0.746 0.143 87.5);
  --line: oklch(0.8 0.06 60 / 25%);
  --shadow-1: 0 2px 6px oklch(0 0 0 / 45%);
  --shadow-2: 0 8px 24px oklch(0 0 0 / 55%);
  --shadow-3: 0 24px 56px oklch(0 0 0 / 65%);
  background-image: repeating-linear-gradient(0deg, oklch(0.35 0.09 15 / 30%) 0 2px, transparent 2px 28px);
}
.theme-porto.alt-mode thead th { background: var(--accent); color: var(--accent-fg); }
.theme-porto.alt-mode kbd { background: var(--surface-2); border-color: var(--line); border-bottom-color: var(--accent-2); color: var(--accent); }
.theme-porto.alt-mode ::selection { background: var(--accent); color: var(--accent-fg); }
.theme-porto.alt-mode tbody tr:nth-child(even) { background: oklch(1 0 0 / 4%); }
.theme-porto.alt-mode tbody tr:hover { background: oklch(1 0 0 / 8%); }
.theme-porto.alt-mode input, .theme-porto.alt-mode select, .theme-porto.alt-mode textarea { background: oklch(0.27 0.095 14); border-color: var(--line); color: var(--fg); }
.theme-porto.alt-mode input:focus-visible, .theme-porto.alt-mode select:focus-visible, .theme-porto.alt-mode textarea:focus-visible { outline-color: var(--accent-2); }
.theme-porto.alt-mode .themed-border { border-image: repeating-linear-gradient(90deg, oklch(0.746 0.143 87.5) 0 10px, oklch(0.385 0.115 12.1) 10px 20px) 1; }
.theme-porto.alt-mode h1 { color: #e8d5b5; }
.theme-porto.alt-mode h1::after { background: #d3a625; }

/* Bridge shadcn semantic variables to the theme tokens so stock shadcn/ui
   components are skinned by the theme. Scope-safe: applies inside the theme
   class only. */
[class*="theme-"] {
  --background: var(--bg);
  --foreground: var(--fg);
  --card: var(--surface);
  --card-foreground: var(--fg);
  --popover: var(--surface);
  --popover-foreground: var(--fg);
  --primary: var(--accent);
  --primary-foreground: var(--accent-fg);
  --secondary: var(--surface-2);
  --secondary-foreground: var(--fg);
  --muted: var(--surface-2);
  --muted-foreground: var(--fg-muted);
  --accent-foreground: var(--accent-fg);
  --border: var(--line);
  --input: var(--line);
  --ring: var(--accent);
  --destructive: var(--danger);
  --destructive-foreground: var(--accent-fg);

  /* Full app surface: sidebar, charts, app-level font + shadow + tracking vars.
     These are what real products (shadcn full kit, RootCX-style UI kits) consume —
     without them a retrofit looks half-themed. */
  --sidebar: var(--surface-2);
  --sidebar-foreground: var(--fg);
  --sidebar-primary: var(--accent);
  --sidebar-primary-foreground: var(--accent-fg);
  --sidebar-accent: color-mix(in oklab, var(--accent) 12%, var(--surface-2));
  --sidebar-accent-foreground: var(--fg);
  --sidebar-border: var(--line);
  --sidebar-ring: var(--accent);

  --chart-1: var(--accent);
  --chart-2: var(--accent-2);
  --chart-3: var(--success);
  --chart-4: var(--warning);
  --chart-5: var(--danger);

  --font-sans: var(--font-body);
  --font-heading: var(--font-app, var(--font-display));
  --font-serif: var(--font-display);

  --shadow-2xs: var(--shadow-1);
  --shadow-xs: var(--shadow-1);
  --shadow-sm: var(--shadow-1);
  --shadow: var(--shadow-2);
  --shadow-md: var(--shadow-2);
  --shadow-lg: var(--shadow-3);
  --shadow-xl: var(--shadow-3);
  --shadow-2xl: var(--shadow-3);

  --tracking-normal: 0em;
}

/* Base experience: make the theme own the canvas and native elements even in
   apps that never adopted semantic classes. Scoped to the theme wrapper. */
[class*="theme-"] {
  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}
[class*="theme-"] :is(h1, h2, h3, h4) { font-family: var(--font-display); }
[class*="theme-"] :is(code, pre, kbd, samp) { font-family: var(--font-mono); }
[class*="theme-"] ::selection { background: color-mix(in oklab, var(--accent) 30%, transparent); }

/* OPT-IN HARD MODE — add "sf-enforce" beside the theme class when the host app
   bakes font/shadow/radius literals into its compiled utilities (a var bridge
   cannot beat a literal). Targeted !important, fonts and surfaces only. */
[class*="theme-"].sf-enforce { font-family: var(--font-body) !important; }
[class*="theme-"].sf-enforce :is(h1, h2, h3, h4, [class*="font-heading"]) {
  font-family: var(--font-app, var(--font-display)) !important;
  letter-spacing: var(--tracking-display) !important;
}
/* Data stays data: metrics/KPIs keep the body face with aligned lining figures.
   The display face is for headlines ONLY — never on numbers. Opt specific
   elements INTO the display face with data-sf="display". */
[class*="theme-"] :is([class*="text-2xl"], [class*="text-3xl"], [class*="text-4xl"], [class*="text-5xl"]) {
  font-variant-numeric: lining-nums tabular-nums;
}
[class*="theme-"].sf-enforce [data-sf="display"] {
  font-family: var(--font-display) !important;
  letter-spacing: var(--tracking-display) !important;
}
[class*="theme-"] :is(.sf-num, [data-sf="num"]) {
  font-family: var(--font-body) !important;
  font-variant-numeric: lining-nums tabular-nums;
}
[class*="theme-"].sf-enforce :is(button, [role="button"]) { font-family: var(--font-ui, var(--font-body)) !important; }
[class*="theme-"].sf-enforce :is(code, pre, kbd) { font-family: var(--font-mono) !important; }
[class*="theme-"].sf-enforce :is(.bg-card, [class*="card"]) {
  box-shadow: var(--shadow-2) !important;
  border-radius: var(--radius-lg) !important;
  border: var(--border-width) solid var(--line) !important;
}
[class*="theme-"].sf-enforce :is([class*="shadow-sm"], [class*="shadow-md"]) { box-shadow: var(--shadow-1) !important; }
[class*="theme-"].sf-enforce :is([class*="shadow-lg"], [class*="shadow-xl"]) { box-shadow: var(--shadow-3) !important; }
